//nahi
import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { Container, Card, Row, Col, Badge, Button } from 'react-bootstrap';
import { getProviderProfile } from '../../services/providerService';

const ProviderProfileView = () => {
  const navigate = useNavigate();
  const [profile, setProfile] = useState(null);

  useEffect(() => {
    const fetchProfile = async () => {
      const res = await getProviderProfile();
      setProfile(res.data);
    };
    fetchProfile();
  }, []);

  if (!profile) return <Container className="py-5">Loading...</Container>;

  return (
    <Container className="py-5">
      <Card className="shadow-sm">
        <Card.Body>
          <div className="d-flex justify-content-between align-items-center mb-4">
            <h2>My Provider Profile</h2>
            <Button variant="outline-success" onClick={() => navigate('/provider/dashboard')}>Back to Dashboard</Button>
          </div>
          <Row>
            <Col md={8}>
              <p><strong>Bio:</strong> {profile.bio}</p>
              <p><strong>Experience:</strong> {profile.experience} years</p>
              <p><strong>Hourly Rate:</strong> ${profile.hourlyRate}/hr</p>
              <p><strong>Service Areas:</strong> {profile.serviceAreas?.join(', ')}</p>
              <div className="mt-3">
                <strong>Specializations: </strong>
                {profile.specializations?.map(spec => (
                  <Badge bg="success" className="me-2" key={spec._id}>{spec.name}</Badge>
                ))}
              </div>
            </Col>
          </Row>
        </Card.Body>
      </Card>
    </Container>
  );
};

export default ProviderProfileView;
